export { ChromaSearchStrategy } from './strategies/ChromaSearchStrategy.js';
export { SQLiteSearchStrategy } from './strategies/SQLiteSearchStrategy.js';
export { HybridSearchStrategy } from './strategies/HybridSearchStrategy.js';

export * from './types.js';

import {
  StrategySearchOptions,
  StrategySearchResult,
  SEARCH_CONSTANTS,
  ChromaMetadata,
  DateRange,
  ObservationSearchResult,
  SessionSummarySearchResult,
  UserPromptSearchResult
} from '../types.js';
import { ChromaSync } from '../../../sync/ChromaSync.js';
import { SessionStore } from '../../../sqlite/SessionStore.js';
import { logger } from '../../../../utils/logger.js';
import { normalizePlatformSource } from '../../../../shared/platform-source.js';

export class ChromaSearchStrategy {
  constructor(
    private chromaSync: ChromaSync,
    private sessionStore: SessionStore
  ) {}

  private emptyResult(strategy: 'chroma'): StrategySearchResult {
    return {
      results: { observations: [], sessions: [], prompts: [] },
      usedChroma: true,
      strategy
    };
  }

  async search(options: StrategySearchOptions): Promise<StrategySearchResult> {
    const {
      query,
      searchType = 'all',
      obsType,
      concepts,
      files,
      limit = SEARCH_CONSTANTS.DEFAULT_LIMIT,
      project,
      platformSource,
      dateRange,
      orderBy = 'date_desc'
    } = options;

    if (!query) {
      return this.emptyResult('chroma');
    }

    const searchObservations = searchType === 'all' || searchType === 'observations';
    const searchSessions = searchType === 'all' || searchType === 'sessions';
    const searchPrompts = searchType === 'all' || searchType === 'prompts';

    const whereFilter = this.buildWhereFilter(searchType, project, platformSource);

    logger.debug('SEARCH', 'ChromaSearchStrategy: Querying Chroma', { query, searchType });

    return await this.executeChromaSearch(query, whereFilter, {
      searchObservations, searchSessions, searchPrompts,
      obsType, concepts, files, orderBy, limit, project, platformSource, dateRange
    });
  }

  private async executeChromaSearch(
    query: string,
    whereFilter: Record<string, any> | undefined,
    options: {
      searchObservations: boolean;
      searchSessions: boolean;
      searchPrompts: boolean;
      obsType?: string | string[];
      concepts?: string | string[];
      files?: string | string[];
      orderBy: 'relevance' | 'date_desc' | 'date_asc';
      limit: number;
      project?: string;
      platformSource?: string;
      dateRange?: DateRange;
    }
  ): Promise<StrategySearchResult> {
    const chromaResults = await this.chromaSync.queryChroma(
      query,
      SEARCH_CONSTANTS.CHROMA_BATCH_SIZE,
      whereFilter
    );

    if (chromaResults.ids.length === 0) {
      return {
        results: { observations: [], sessions: [], prompts: [] },
        usedChroma: true,
        strategy: 'chroma'
      };
    }

    const recentItems = this.filterByRecency(chromaResults, options.dateRange);
    const categorized = this.categorizeByDocType(recentItems, options);

    let observations: ObservationSearchResult[] = [];
    let sessions: SessionSummarySearchResult[] = [];
    let prompts: UserPromptSearchResult[] = [];

    const sqlOrderBy = options.orderBy;

    if (categorized.obsIds.length > 0) {
      const obsOptions = {
        type: options.obsType,
        concepts: options.concepts,
        files: options.files,
        orderBy: sqlOrderBy,
        limit: options.limit,
        project: options.project,
        platformSource: options.platformSource
      };
      observations = this.sessionStore.getObservationsByIds(categorized.obsIds, obsOptions);
    }

    if (categorized.sessionIds.length > 0) {
      sessions = this.sessionStore.getSessionSummariesByIds(categorized.sessionIds, {
        orderBy: sqlOrderBy,
        limit: options.limit,
        project: options.project,
        platformSource: options.platformSource
      });
    }

    if (categorized.promptIds.length > 0) {
      prompts = this.sessionStore.getUserPromptsByIds(categorized.promptIds, {
        orderBy: sqlOrderBy,
        limit: options.limit,
        project: options.project,
        platformSource: options.platformSource
      });
    }

    return {
      results: { observations, sessions, prompts },
      usedChroma: true,
      strategy: 'chroma'
    };
  }

  private buildWhereFilter(searchType: string, project?: string, platformSource?: string): Record<string, any> | undefined {
    const filters: Array<Record<string, any>> = [];

    switch (searchType) {
      case 'observations':
        filters.push({ doc_type: 'observation' });
        break;
      case 'sessions':
        filters.push({ doc_type: 'session_summary' });
        break;
      case 'prompts':
        filters.push({ doc_type: 'user_prompt' });
        break;
      default:
        break;
    }

    if (project) {
      filters.push({
        $or: [
          { project },
          { merged_into_project: project }
        ]
      });
    }

    if (platformSource) {
      filters.push({ platform_source: normalizePlatformSource(platformSource) });
    }

    if (filters.length === 0) {
      return undefined;
    }
    if (filters.length === 1) {
      return filters[0];
    }
    return { $and: filters };
  }

  private filterByRecency(chromaResults: {
    ids: number[];
    metadatas: ChromaMetadata[];
  }, dateRange?: DateRange): Array<{ id: number; meta: ChromaMetadata }> {
    let startEpoch: number | undefined;
    let endEpoch: number | undefined;

    if (dateRange) {
      if (dateRange.start) {
        startEpoch = typeof dateRange.start === 'number'
          ? dateRange.start
          : new Date(dateRange.start).getTime();
      }
      if (dateRange.end) {
        endEpoch = typeof dateRange.end === 'number'
          ? dateRange.end
          : new Date(dateRange.end).getTime();
      }
    } else {
      startEpoch = Date.now() - SEARCH_CONSTANTS.RECENCY_WINDOW_MS;
    }

    const metadataByIdMap = new Map<number, ChromaMetadata>();
    for (const meta of chromaResults.metadatas) {
      if (meta?.sqlite_id !== undefined && !metadataByIdMap.has(meta.sqlite_id)) {
        metadataByIdMap.set(meta.sqlite_id, meta);
      }
    }

    return chromaResults.ids
      .map(id => ({
        id,
        meta: metadataByIdMap.get(id) as ChromaMetadata
      }))
      .filter(item => item.meta && item.meta.created_at_epoch != null
        && (!startEpoch || item.meta.created_at_epoch >= startEpoch)
        && (!endEpoch || item.meta.created_at_epoch <= endEpoch));
  }

  private categorizeByDocType(
    items: Array<{ id: number; meta: ChromaMetadata }>,
    options: {
      searchObservations: boolean;
      searchSessions: boolean;
      searchPrompts: boolean;
    }
  ): { obsIds: number[]; sessionIds: number[]; promptIds: number[] } {
    const obsIds: number[] = [];
    const sessionIds: number[] = [];
    const promptIds: number[] = [];

    for (const item of items) {
      const docType = item.meta?.doc_type;
      if (docType === 'observation' && options.searchObservations) {
        obsIds.push(item.id);
      } else if (docType === 'session_summary' && options.searchSessions) {
        sessionIds.push(item.id);
      } else if (docType === 'user_prompt' && options.searchPrompts) {
        promptIds.push(item.id);
      }
    }

    return { obsIds, sessionIds, promptIds };
  }
}

import {
  StrategySearchOptions,
  SEARCH_CONSTANTS,
  ObservationSearchResult,
  SessionSummarySearchResult
} from '../types.js';
import { ChromaSync } from '../../../sync/ChromaSync.js';
import { SessionStore } from '../../../sqlite/SessionStore.js';
import { SessionSearch } from '../../../sqlite/SessionSearch.js';
import { logger } from '../../../../utils/logger.js';
import { normalizePlatformSource } from '../../../../shared/platform-source.js';

export class HybridSearchStrategy {
  constructor(
    private chromaSync: ChromaSync,
    private sessionStore: SessionStore,
    private sessionSearch: SessionSearch
  ) {}

  async findByFile(
    filePath: string,
    options: StrategySearchOptions
  ): Promise<{
    observations: ObservationSearchResult[];
    sessions: SessionSummarySearchResult[];
    usedChroma: boolean;
  }> {
    const { limit = SEARCH_CONSTANTS.DEFAULT_LIMIT, project, platformSource, dateRange, orderBy } = options;
    const filterOptions = { limit, project, platformSource, dateRange, orderBy };

    logger.debug('SEARCH', 'HybridSearchStrategy: findByFile', { filePath });

    const metadataResults = this.sessionSearch.findByFile(filePath, filterOptions);
    const sessions = metadataResults.sessions;

    if (metadataResults.observations.length === 0) {
      return { observations: [], sessions, usedChroma: false };
    }

    const ids = metadataResults.observations.map(obs => obs.id);

    return await this.rankAndHydrateForFile(filePath, ids, metadataResults.observations, { limit, project, platformSource, orderBy }, sessions);
  }

  private async rankAndHydrateForFile(
    filePath: string,
    metadataIds: number[],
    fallbackObservations: ObservationSearchResult[],
    options: { limit: number; project?: string; platformSource?: string; orderBy?: StrategySearchOptions['orderBy'] },
    sessions: SessionSummarySearchResult[]
  ): Promise<{ observations: ObservationSearchResult[]; sessions: SessionSummarySearchResult[]; usedChroma: boolean }> {
    const chromaResults = await this.chromaSync.queryChroma(
      filePath,
      Math.min(metadataIds.length, SEARCH_CONSTANTS.CHROMA_BATCH_SIZE),
      this.buildObservationWhereFilter(options.project, options.platformSource)
    );

    const rankedIds = this.intersectWithRanking(metadataIds, chromaResults.ids);

    if (rankedIds.length > 0) {
      const observations = this.sessionStore.getObservationsByIds(rankedIds, {
        orderBy: 'relevance',
        limit: options.limit,
        project: options.project,
        platformSource: options.platformSource
      });
      observations.sort((a, b) => rankedIds.indexOf(a.id) - rankedIds.indexOf(b.id));

      return { observations, sessions, usedChroma: true };
    }

    if (options.platformSource) {
      return {
        observations: this.sortMetadataFallback(fallbackObservations, options.limit, options.orderBy),
        sessions,
        usedChroma: false
      };
    }

    return { observations: [], sessions, usedChroma: false };
  }

  private sortMetadataFallback(
    observations: ObservationSearchResult[],
    limit: number,
    orderBy: StrategySearchOptions['orderBy'] = 'date_desc'
  ): ObservationSearchResult[] {
    const sorted = [...observations].sort((a, b) => {
      const epochDelta = a.created_at_epoch - b.created_at_epoch;
      if (epochDelta !== 0) {
        return orderBy === 'date_asc' ? epochDelta : -epochDelta;
      }
      const idDelta = a.id - b.id;
      return orderBy === 'date_asc' ? idDelta : -idDelta;
    });
    return sorted.slice(0, limit);
  }

  private buildObservationWhereFilter(project?: string, platformSource?: string): Record<string, any> {
    const filters: Array<Record<string, any>> = [{ doc_type: 'observation' }];
    if (project) {
      filters.push({ project });
    }
    if (platformSource) {
      filters.push({ platform_source: normalizePlatformSource(platformSource) });
    }
    return filters.length === 1 ? filters[0] : { $and: filters };
  }

  private intersectWithRanking(metadataIds: number[], chromaIds: number[]): number[] {
    const metadataSet = new Set(metadataIds);
    const rankedIds: number[] = [];

    for (const chromaId of chromaIds) {
      if (metadataSet.has(chromaId) && !rankedIds.includes(chromaId)) {
        rankedIds.push(chromaId);
      }
    }

    return rankedIds;
  }
}

import {
  StrategySearchOptions,
  StrategySearchResult,
  SEARCH_CONSTANTS,
  ObservationSearchResult,
  SessionSummarySearchResult,
  UserPromptSearchResult
} from '../types.js';
import { SessionSearch } from '../../../sqlite/SessionSearch.js';
import { logger } from '../../../../utils/logger.js';

export class SQLiteSearchStrategy {
  constructor(private sessionSearch: SessionSearch) {}

  private emptyResult(strategy: 'sqlite'): StrategySearchResult {
    return {
      results: { observations: [], sessions: [], prompts: [] },
      usedChroma: false,
      strategy
    };
  }

  async search(options: StrategySearchOptions): Promise<StrategySearchResult> {
    const {
      query,
      searchType = 'all',
      obsType,
      concepts,
      files,
      limit = SEARCH_CONSTANTS.DEFAULT_LIMIT,
      offset = 0,
      project,
      platformSource,
      dateRange,
      orderBy = 'date_desc'
    } = options;

    const searchObservations = searchType === 'all' || searchType === 'observations';
    const searchSessions = searchType === 'all' || searchType === 'sessions';
    const searchPrompts = searchType === 'all' || searchType === 'prompts';

    let observations: ObservationSearchResult[] = [];
    let sessions: SessionSummarySearchResult[] = [];
    let prompts: UserPromptSearchResult[] = [];

    const baseOptions = { limit, offset, orderBy, project, platformSource, dateRange };

    logger.debug('SEARCH', 'SQLiteSearchStrategy: SQLite query', {
      searchType,
      hasQuery: !!query,
      hasDateRange: !!dateRange,
      hasProject: !!project
    });

    const obsOptions = searchObservations ? { ...baseOptions, type: obsType, concepts, files } : null;

    try {
      return this.executeSqliteSearch(query, obsOptions, searchSessions, searchPrompts, baseOptions);
    } catch (error) {
      const errorObj = error instanceof Error ? error : new Error(String(error));
      logger.error('WORKER', 'SQLiteSearchStrategy: Search failed', {}, errorObj);
      return this.emptyResult('sqlite');
    }
  }

  private executeSqliteSearch(
    query: string | undefined,
    obsOptions: Record<string, any> | null,
    searchSessions: boolean,
    searchPrompts: boolean,
    baseOptions: Record<string, any>
  ): StrategySearchResult {
    let observations: ObservationSearchResult[] = [];
    let sessions: SessionSummarySearchResult[] = [];
    let prompts: UserPromptSearchResult[] = [];

    if (obsOptions) {
      observations = this.sessionSearch.searchObservations(query, obsOptions);
    }
    if (searchSessions) {
      sessions = this.sessionSearch.searchSessions(query, baseOptions);
    }
    if (searchPrompts) {
      prompts = this.sessionSearch.searchUserPrompts(query, baseOptions);
    }

    return {
      results: { observations, sessions, prompts },
      usedChroma: false,
      strategy: 'sqlite'
    };
  }

  findByFile(filePath: string, options: StrategySearchOptions): {
    observations: ObservationSearchResult[];
    sessions: SessionSummarySearchResult[];
  } {
    const { limit = SEARCH_CONSTANTS.DEFAULT_LIMIT, project, platformSource, dateRange, orderBy = 'date_desc' } = options;
    return this.sessionSearch.findByFile(filePath, { limit, project, platformSource, dateRange, orderBy });
  }
}

